package com.Senai.Mubak.controller; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import com.Senai.Mubak.service.UsuarioService; @Controller @RequestMapping("/admin/usuarios") public class AdminUsuarioController{final UsuarioService s;public AdminUsuarioController(UsuarioService s){this.s=s;}@GetMapping String l(Model m){m.addAttribute("usuarios",s.listar());return "admin/usuarios";}@GetMapping("/novo")String n(){return "admin/usuario-form";}@PostMapping String c(@RequestParam String usuario,@RequestParam String senha){s.rootUser(usuario,senha);return "redirect:/admin/usuarios";}}